#!/usr/bin/env bash
# Office Simulator 3.0.1 · Установщик для Ubuntu
# Запуск мастера: bash install.sh     Справка: bash install.sh --help
# Local prerequisite for the Ubuntu controller. Embedded in the released install.sh.
python_error() {
    printf 'Ошибка · %s\n' "$1" >&2
    exit 1
}

python_works() {
    [ -x "$1" ] && "$1" -I -B -c "$python_probe" </dev/null >/dev/null 2>&1
}

find_python() {
    local candidate path
    for candidate in python3 python3.15 python3.14 python3.13 python3.12 python3.11 python; do
        path=$(type -P "$candidate") || continue
        if python_works "$path"; then python_bin=$path; return 0; fi
    done
    return 1
}

url_component() {
    local LC_ALL=C raw=$1 i char encoded=
    for ((i=0; i<${#raw}; i++)); do
        char=${raw:i:1}
        case "$char" in
            [a-zA-Z0-9._~-]) encoded+=$char ;;
            *) printf -v char '%%%02X' "'$char"; encoded+=$char ;;
        esac
    done
    printf '%s' "$encoded"
}

python_route() {
    local proxy= login= address port
    while [ "$#" -gt 0 ]; do
        case "$1" in
            --proxy|--proxy-user)
                [[ $# -ge 2 && -n "$2" && "$2" != --* ]] || python_error "После $1 требуется значение."
                if [ "$1" = --proxy ]; then proxy=$2; else login=$2; fi
                shift ;;
            --proxy=*) proxy=${1#*=}; [ -n "$proxy" ] || python_error "Введите адрес SOCKS5." ;;
            --proxy-user=*) login=${1#*=}; [ -n "$login" ] || python_error "Введите логин SOCKS5." ;;
            --direct) route_mode=direct ;;
            --) break ;;
        esac
        shift
    done
    if [ -z "$proxy" ]; then
        [ -z "$login" ] || python_error "Для --proxy-user укажите --proxy хост:порт."
        return 0
    fi
    [ "$route_mode" != direct ] || python_error "Выберите один маршрут: --direct или --proxy."
    local pattern='^(socks5h?://)?(\[[0-9A-Fa-f:.]+\]|[[:alnum:]][[:alnum:].-]*):([0-9]{1,5})/?$'
    [[ "$proxy" =~ $pattern ]] || python_error "Адрес SOCKS5 вводится как хост:порт. Логин передаётся через --proxy-user."
    address=${BASH_REMATCH[2]} port=${BASH_REMATCH[3]}
    (( 10#$port > 0 && 10#$port < 65536 )) || python_error "Неверный порт SOCKS5."
    route_mode=proxy
    if [ -z "$login" ] && ( : < /dev/tty ) 2>/dev/null; then
        printf 'SOCKS5 login (Enter для доступа без пароля) > ' >&2
        IFS= read -r login < /dev/tty || python_error "Ввод логина прерван."
        python_proxy_login=$login
    fi
    if [ -n "$login" ]; then
        [[ "$login" != *:* && "$login" != *[[:cntrl:]]* ]] || python_error "Введите логин SOCKS5 отдельно от пароля."
        ( : < /dev/tty ) 2>/dev/null || python_error "Для ввода пароля SOCKS5 нужен терминал."
        python_tty_mode=$(stty -g < /dev/tty) || python_error "Не удалось прочитать настройки терминала."
        stty -echo < /dev/tty || python_error "Не удалось включить скрытый ввод пароля."
        printf 'SOCKS5 password (%s) > ' "$login" >&2
        IFS= read -r python_proxy_password < /dev/tty || python_error "Ввод пароля прерван."
        stty "$python_tty_mode" < /dev/tty || python_error "Не удалось восстановить настройки терминала."
        python_tty_mode=
        printf '\n' >&2
        [[ -n "$python_proxy_password" && "$python_proxy_password" != *[[:cntrl:]]* ]] || python_error "Требуется пароль SOCKS5."
        local LC_ALL=C
        (( ${#login} <= 255 && ${#python_proxy_password} <= 255 )) || python_error "Для SOCKS5 допустимо до 255 байт на поле."
        proxy_url="socks5h://$(url_component "$login"):$(url_component "$python_proxy_password")@$address:$port"
    else
        proxy_url="socks5h://$address:$port"
    fi
}

apt_for_python() {
    local name candidate config="$office_tmp/python-apt.conf" scheme
    local -a command=(apt-get -q -o Dpkg::Lock::Timeout=60 -o Acquire::Retries=1)
    local -a environment=(env)
    if [ "$route_mode" != system ]; then
        (
            for scheme in http https; do
                printf '#clear Acquire::%s::Proxy;\n#clear Acquire::%s::Proxy-Auto-Detect;\n#clear Acquire::%s::ProxyAutoDetect;\n' \
                    "$scheme" "$scheme" "$scheme" || exit 1
                printf 'Acquire::%s::Proxy "%s";\n' "$scheme" "${proxy_url:-DIRECT}" || exit 1
            done
            printf '%s\n' 'Acquire::EnableSrvRecords "false";'
        ) > "$config" || python_error "Не удалось записать параметры маршрута APT."
        command+=(-c "$config")
        environment+=(-u APT_CONFIG -u http_proxy -u https_proxy -u all_proxy -u no_proxy
                      -u HTTP_PROXY -u HTTPS_PROXY -u ALL_PROXY -u NO_PROXY)
    fi
    environment+=(LC_ALL=C DEBIAN_FRONTEND=noninteractive)
    local -a package_cache=("${environment[@]}" apt-cache)
    if (( EUID != 0 )); then
        command -v sudo >/dev/null || return 1
        if ! sudo -n -v >/dev/null 2>&1; then
            ( : < /dev/tty ) 2>/dev/null || return 1
            printf 'Для установки пакета Python в Ubuntu нужны права sudo.\n' >&2
            if ! sudo -v </dev/tty; then
                printf 'Права sudo недоступны. Установлю Python в личный каталог.\n' >&2
                return 1
            fi
        fi
        environment=(sudo -- "${environment[@]}")
    fi
    printf 'Проверяю версии Python в репозиториях Ubuntu…\n' >&2
    if ! "${environment[@]}" "${command[@]}" -o APT::Update::Error-Mode=any update > "$office_tmp/python-apt.log" 2>&1; then
        python_error "APT не смог обновить индексы. Проверьте доступ к настроенным зеркалам и выбранный маршрут."
    fi
    for name in python3 python3.15 python3.14 python3.13 python3.12 python3.11; do
        candidate=$("${package_cache[@]}" policy "?exact-name($name)" 2>/dev/null | awk '$1=="Candidate:" {print $2}') ||
            python_error "APT не смог прочитать список доступных пакетов."
        # Ubuntu 22.04 also publishes 3.11.0~rc1. Only final releases qualify.
        if [[ "$candidate" =~ ^([0-9]+:)?3\.([0-9]+)\.[0-9]+($|[-+]|~[0-9]|~ubuntu) ]] && (( 10#${BASH_REMATCH[2]} >= 11 )); then
            printf 'Устанавливаю пакет %s (%s) через APT…\n' "$name" "$candidate" >&2
            if ! "${environment[@]}" "${command[@]}" -y --no-install-recommends install "$name" ca-certificates tzdata > "$office_tmp/python-apt.log" 2>&1; then
                python_error "APT не смог установить $name. Проверьте доступ к репозиториям и состояние dpkg."
            fi
            if python_works "/usr/bin/$name"; then python_bin=/usr/bin/$name; return 0; fi
            find_python || python_error "Установленный пакет $name не предоставил рабочий Python 3.11 или новее."
            return 0
        fi
    done
    printf 'В настроенных репозиториях доступен только старый Python или предварительный выпуск. Установлю отдельную копию для мастера.\n' >&2
    local -a missing=()
    for name in curl tar gzip; do
        if ! command -v "$name" >/dev/null; then missing+=("$name"); fi
    done
    if [ ! -s /etc/ssl/certs/ca-certificates.crt ]; then missing+=(ca-certificates); fi
    if (( ${#missing[@]} )); then
        "${environment[@]}" "${command[@]}" -y --no-install-recommends install "${missing[@]}" > "$office_tmp/python-apt.log" 2>&1 ||
            python_error "APT не смог подготовить утилиты загрузки Python."
    fi
    return 1
}

python_private_dir() {
    local path=$1
    mkdir -p "$path" || python_error "Не удалось создать $path."
    [[ -d "$path" && ! -L "$path" && -O "$path" && $(stat -c '%a' "$path") = 700 ]] ||
        python_error "Для личного каталога $path требуются текущий владелец и права 700."
}

install_private_python() {
    local url sum tool
    local -a fetch=(--disable --fail --silent --show-error --location --proto '=https' --proto-redir '=https'
                    --connect-timeout 20 --max-time 300 --retry 2)
    [ -n "$python_sha" ] || python_error "Для этой архитектуры нужен доступный пакет стабильного Python 3.11 или новее."
    for tool in curl tar gzip sha256sum; do
        command -v "$tool" >/dev/null || python_error "Для установки Python в личный каталог нужна команда $tool. Запустите мастер в терминале с доступом к sudo или установите эту утилиту."
    done
    python_private_dir "$app_dir"
    python_private_dir "$app_dir/python"
    python_stage=$(mktemp -d "$app_dir/python/.install.XXXXXXXX") || python_error "Не удалось создать временный каталог для Python."
    url="https://github.com/astral-sh/python-build-standalone/releases/download/$release/cpython-$version%2B$release-$python_target-install_only_stripped.tar.gz"
    printf 'Загружаю CPython %s для Ubuntu в личный каталог…\n' "$version" >&2
    fetch+=(--output "$python_stage/runtime.tar.gz")
    case "$route_mode" in
        proxy) printf 'proxy = "%s"\nnoproxy = ""\n' "$proxy_url" | curl "${fetch[@]}" --config - "$url" ;;
        direct) curl "${fetch[@]}" --proxy '' --noproxy '*' "$url" ;;
        system) curl "${fetch[@]}" "$url" ;;
    esac || python_error "Не удалось скачать CPython с GitHub. Проверьте маршрут и повторите запуск."
    sum=$(sha256sum < "$python_stage/runtime.tar.gz") || python_error "Для проверки архива требуется sha256sum."
    [[ ${sum%% *} = "$python_sha" ]] || python_error "Контрольная сумма архива Python не совпала."
    tar --no-same-owner -xzf "$python_stage/runtime.tar.gz" -C "$python_stage" || python_error "Не удалось распаковать Python."
    python_works "$python_stage/python/bin/python3" || python_error "Скачанный Python не запускается на этой системе."
    chmod 700 "$python_stage/python"
    printf '%s\n' "$python_sha" > "$python_stage/python/.office-python"
    # Publish a fully validated tree, even if two controllers start together.
    "$python_stage/python/bin/python3" -I -B - "$python_stage" "$dest" "$python_sha" "$python_probe" <<'OFFICE_PYTHON_PUBLISH'
import fcntl, subprocess, sys
from pathlib import Path

stage, dest = map(Path, sys.argv[1:3])
digest, probe = sys.argv[3:]
with open(dest.parent / ".install.lock", "a") as lock:
    fcntl.flock(lock, fcntl.LOCK_EX)
    replaced = False
    if dest.exists() or dest.is_symlink():
        marker = dest / ".office-python"
        if dest.is_symlink() or not dest.is_dir() or marker.is_symlink() or not marker.is_file() or marker.read_text().strip() != digest:
            sys.exit(f"Каталог {dest} занят другой установкой.")
        try:
            rc = subprocess.run([str(dest / "bin/python3"), "-I", "-B", "-c", probe],
                                stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=15).returncode
        except (OSError, subprocess.TimeoutExpired):
            rc = 1
        if rc == 0:
            sys.exit(0)
        dest.rename(stage / "previous")
        replaced = True
    try:
        (stage / "python").rename(dest)
    except OSError:
        if replaced:
            (stage / "previous").rename(dest)
        raise
OFFICE_PYTHON_PUBLISH
    python_bin=$dest/bin/python3
    python_works "$python_bin" || python_error "Не удалось запустить установленный Python в $dest."
    printf 'Python %s готов · %s\n' "$version" "$python_bin" >&2
}

prepare_python() {
    local python_probe='import ctypes, fcntl, ssl, sys, zipfile, zlib, zoneinfo; sys.exit(sys.version_info < (3, 11) or sys.version_info.releaselevel != "final")'
    if find_python; then return; fi
    if ! grep -Eq "^ID=(ubuntu|'ubuntu'|\"ubuntu\")$" /etc/os-release 2>/dev/null; then
        python_error "Автоматическая установка Python настроена для Ubuntu. Для запуска на другой системе нужен Python 3.11 или новее."
    fi
    local version=3.14.10 release=20261110 python_sha= python_target= app_dir dest route_mode=system proxy_url=
    case "$(uname -m)" in
        aarch64|arm64) python_target=aarch64-unknown-linux-gnu; python_sha=38fd50f07170adc29d481913d1c30b17ecb538fbe290315fe1f83d84fdd5b694 ;;
        x86_64|amd64) python_target=x86_64-unknown-linux-gnu; python_sha=c2ff2e97422f5d3896a16e0317fd212ba977bbf2688d93a6f7a03d817506bd30 ;;
    esac
    app_dir=${XDG_DATA_HOME:-${HOME:?}/.local/share}/office-simulator
    [[ "$app_dir" = /* ]] || python_error "Для личного каталога нужен абсолютный путь."
    dest=$app_dir/python/$version-$release-$python_target
    if [[ -n "$python_sha" && ( -e "$dest" || -L "$dest" ) ]]; then
        python_private_dir "$app_dir"
        python_private_dir "$app_dir/python"
        if [[ ! -d "$dest" || -L "$dest" || ! -O "$dest" || ! -f "$dest/.office-python" ||
              -L "$dest/.office-python" || "$(< "$dest/.office-python")" != "$python_sha" ]]; then
            python_error "Каталог $dest занят другой установкой."
        fi
        if python_works "$dest/bin/python3"; then python_bin=$dest/bin/python3; return; fi
    fi
    python_route "$@"
    if command -v apt-get >/dev/null && command -v apt-cache >/dev/null && apt_for_python; then return; fi
    install_private_python
}

office_install() (
    set +x
    set +a
    set -eu -o pipefail
    umask 077
    unset OFFICE_INSTALL_PROXY_FD python_proxy_password proxy_url
    local python_bin= python_stage= python_proxy_login= python_proxy_password= python_tty_mode= office_tmp
    office_tmp=$(mktemp -d "${TMPDIR:-/tmp}/office-installer.XXXXXXXX")
    trap 'if [ -n "$python_tty_mode" ]; then (stty "$python_tty_mode" < /dev/tty) 2>/dev/null || :; fi
          rm -rf -- "$office_tmp"
          if [ -n "$python_stage" ]; then rm -rf -- "$python_stage"; fi' EXIT
    trap 'exit 130' INT
    trap 'exit 143' TERM HUP
    prepare_python "$@"
    rm -f -- "$office_tmp/python-apt.conf" "$office_tmp/python-apt.log"
    if [ -n "$python_stage" ]; then rm -rf -- "$python_stage"; python_stage=; fi
    if [ -n "$python_proxy_login" ]; then set -- "$@" --proxy-user "$python_proxy_login"; fi
    "$python_bin" -I -B -c '
import base64, hashlib, io, os, sys, zipfile
from pathlib import Path, PurePosixPath
try:
    payload = base64.b64decode(b"".join(sys.stdin.buffer.read().split()), validate=True)
    if len(payload) != 2287892 or hashlib.sha256(payload).hexdigest() != "e2115cd4a0ff8b5fc26cc0195a990e10cc4bef1962094968f55540098bfef613":
        raise ValueError
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        for item in archive.infolist():
            name = PurePosixPath(item.filename)
            if name.is_absolute() or ".." in name.parts or (item.external_attr >> 16) != 0o100600:
                raise ValueError
            target = Path(sys.argv[1]) / name
            target.parent.mkdir(parents=True, exist_ok=True)
            with target.open("xb") as file:
                file.write(archive.read(item))
except (ValueError, OSError, zipfile.BadZipFile):
    sys.exit("Не удалось проверить и распаковать комплект Office Simulator.")
' "$office_tmp" <<'OFFICE_SIMULATOR_PAYLOAD'
